SELECT * FROM HDOC_USER_DEFINED_RULES WHERE 1=1
 AND PC = #{pc} 
 AND NUM = #{num} 
 AND MARKET = #{market} 
 AND VARIABLE LIKE CONCAT('%', #{variable}, '%') 
 AND VAL LIKE CONCAT('%', #{val}, '%') 
 AND VS = #{vs} 
 AND VS2 = #{vs2} 
 AND COMMENTS LIKE CONCAT('%', #{comments}, '%') 
 AND ADD_DATE >= #{addDateFrom} 
 AND ADD_DATE <= #{addDateTo} 
 AND DELETE_DATE >= #{deleteDateFrom} 
 AND DELETE_DATE <= #{deleteDateTo} 
 AND REGISTER_USER LIKE CONCAT('%', #{createdByUser}, '%')

mapper.update:
UPDATE HDOC_USER_DEFINED_RULES SET VS = #{vs}, VS2 = #{vs2}, VARIABLE = #{variable}, VAL = #{val},
COMMENTS = #{comments}, ADD_DATE = #{addDate}, DELETE_DATE = #{deleteDate}
WHERE PC = #{pc} AND NUM = #{num} AND MARKET = #{market}
